-- Phase 9 task 4 (ruling 5): the `dead_letter` table, and a REBUILD of
-- `audit_log` (generated by drizzle-kit, then trimmed by hand). SQLite
-- cannot alter a CHECK, and `audit_log_action_check` /
-- `audit_log_target_type_check` need the new `dead_letter.replay`,
-- `dead_letter.discard` and `dead_letter` values, so the table is created
-- anew, copied, dropped and renamed, and its five indexes recreated.
-- No trigger exists on `audit_log` (0007's `user_keep_one_admin` is on
-- `user`), and no table references `audit_log`, so the generated
-- `PRAGMA foreign_keys` toggles (no-ops inside D1's migration transaction)
-- are left out. Rows are copied column for column, `legacy` rows and NULL
-- `actor_id` included. The deploy job runs this against D1 before the
-- Worker deploys (docs/DECISIONS.md, phase 9 task 4).
CREATE TABLE `dead_letter` (
	`id` text PRIMARY KEY NOT NULL,
	`queue` text NOT NULL,
	`origin_queue` text NOT NULL,
	`type` text NOT NULL,
	`attempts` integer NOT NULL,
	`received_at` integer NOT NULL,
	`body` text,
	`replayable` integer NOT NULL,
	`replayed_at` integer,
	`discarded_at` integer,
	`error` text,
	CONSTRAINT "dead_letter_origin_check" CHECK("origin_queue" IN ('email', 'events')),
	CONSTRAINT "dead_letter_replayable_check" CHECK("replayable" IN (0, 1))
);
--> statement-breakpoint
CREATE INDEX `dead_letter_received_at_idx` ON `dead_letter` (`received_at`,`id`);--> statement-breakpoint
CREATE INDEX `dead_letter_open_idx` ON `dead_letter` (`origin_queue`,`received_at`) WHERE "replayed_at" IS NULL AND "discarded_at" IS NULL;--> statement-breakpoint
CREATE TABLE `__new_audit_log` (
	`id` text PRIMARY KEY NOT NULL,
	`actor_id` text,
	`action` text NOT NULL,
	`target_type` text NOT NULL,
	`target_id` text,
	`data` text NOT NULL,
	`created_at` integer NOT NULL,
	FOREIGN KEY (`actor_id`) REFERENCES `user`(`id`) ON UPDATE no action ON DELETE set null,
	CONSTRAINT "audit_log_action_check" CHECK("action" IN ('gesture.create', 'gesture.update', 'gesture.publish', 'gesture.unpublish', 'gesture.delete', 'gesture.bulk_update', 'category.create', 'category.update', 'category.publish', 'category.unpublish', 'category.delete', 'category.reorder', 'user.role_change', 'user.ban', 'user.unban', 'user.delete', 'user.impersonate', 'sponsorship.approve', 'sponsorship.reject', 'sponsorship.request_changes', 'sponsorship.mark_paid', 'sponsorship.cancel', 'sponsorship.retry_render', 'sponsorship.force_expire', 'sponsorship.regenerate_token', 'payment.refund', 'maintenance.enable', 'maintenance.disable', 'export.sponsorships_csv', 'dead_letter.replay', 'dead_letter.discard', 'legacy')),
	CONSTRAINT "audit_log_target_type_check" CHECK("target_type" IN ('gesture', 'category', 'user', 'sponsorship', 'payment', 'list', 'setting', 'system', 'dead_letter'))
);
--> statement-breakpoint
